"""Sorted-insertion helpers."""


def insert_pos(items, value):
    """Index at which to insert `value` into ascending `items`, after any equal entries."""
    lo, hi = 0, len(items)
    while lo < hi:
        mid = (lo + hi) // 2
        if items[mid] < value:
            lo = mid + 1
        else:
            hi = mid
    return lo
